import { useCallback, useEffect, useState } from "react"
import { Image, Pressable, ScrollView, StyleSheet, Text, View, useWindowDimensions } from "react-native"
import { useLocalSearchParams, useRouter } from "expo-router"
import { Heart, MapPin, MessageSquareText, Store } from "lucide-react-native"
import { absoluteUrl, api, currentAccessToken } from "@/lib/api"
import type { Design, Product, VendorDirectoryItem } from "@/types/api"
import { CatalogCard } from "@/components/CatalogCard"
import { AppButton, EmptyState, ErrorState, LoadingState, PageHeader, Screen } from "@/components/ui"
import { useTheme } from "@/theme/theme"

export default function VendorDetailScreen() {
  const { id } = useLocalSearchParams<{ id: string }>(); const router = useRouter(); const { colors } = useTheme(); const { width } = useWindowDimensions(); const [vendor, setVendor] = useState<VendorDirectoryItem | null>(null); const [designs, setDesigns] = useState<Design[]>([]); const [products, setProducts] = useState<Product[]>([]); const [mode, setMode] = useState<"designs" | "products">("designs"); const [loading, setLoading] = useState(true); const [error, setError] = useState("")
  const load = useCallback(async () => { setError(""); try { const [shop, looks, goods] = await Promise.all([api<VendorDirectoryItem>(`/api/vendors/${id}`), api<Design[]>(`/api/designs?vendor_id=${id}`), api<Product[]>(`/api/products?vendor_id=${id}`)]); setVendor(shop); setDesigns(looks); setProducts(goods) } catch (value) { setError((value as Error).message) } finally { setLoading(false) } }, [id])
  useEffect(() => { void load() }, [load])
  if (loading) return <Screen scroll={false}><LoadingState label="Opening vendor shop…" /></Screen>
  if (error || !vendor) return <Screen><PageHeader back title="Vendor shop" /><ErrorState message={error || "Vendor not found"} retry={() => void load()} /></Screen>
  const favorite = async () => { const next = !vendor.is_favorite; setVendor({ ...vendor, is_favorite: next }); try { await api(`/api/vendors/${vendor.id}/favorite`, { method: next ? "POST" : "DELETE" }) } catch { setVendor({ ...vendor, is_favorite: !next }) } }
  const customOrder = () => router.push({ pathname: "/custom-order/[vendorId]" as never, params: { vendorId: String(vendor.id) } })
  const cardWidth = Math.min((width - 52) / 2, 210)
  return <Screen><PageHeader back title={vendor.shop_name} /><View style={[styles.hero, { backgroundColor: colors.surface, borderColor: colors.border }]}><View style={[styles.logo, { backgroundColor: colors.primarySoft }]}>{vendor.logo_url ? <Image source={{ uri: absoluteUrl(vendor.logo_url), headers: currentAccessToken() ? { Authorization: `Bearer ${currentAccessToken()}` } : undefined }} style={styles.logoImage} /> : <Store color={colors.primary} size={34} />}</View><View style={{ flex: 1 }}><Text style={{ color: colors.primary, fontFamily: "Manrope_700Bold", fontSize: 10 }}>VERIFIED VENDOR</Text><Text style={{ color: colors.text, fontFamily: "Fraunces_700Bold", fontSize: 25 }}>{vendor.shop_name}</Text><Text style={{ color: colors.muted, fontFamily: "Manrope_400Regular" }}>Tailored by {vendor.full_name}</Text></View><Pressable onPress={() => void favorite()}><Heart color={vendor.is_favorite ? colors.primary : colors.muted} fill={vendor.is_favorite ? colors.primary : "none"} size={24} /></Pressable></View>{vendor.location && <Text style={{ color: colors.muted, fontFamily: "Manrope_500Medium", marginBottom: 15 }}><MapPin size={14} /> {vendor.location}</Text>}<Text style={{ color: colors.muted, fontFamily: "Manrope_400Regular", lineHeight: 22, marginBottom: 17 }}>{vendor.shop_description || "Custom tailoring and made-to-measure garments from this verified Vastrivo vendor."}</Text>{vendor.accepts_custom_orders && <AppButton onPress={customOrder}><MessageSquareText size={17} /> Custom order</AppButton>}{!!error && <Text style={{ color: colors.danger, marginTop: 10 }}>{error}</Text>}<View style={[styles.tabs, { borderColor: colors.border }]}><Pressable onPress={() => setMode("designs")} style={[styles.tab, mode === "designs" && { backgroundColor: colors.primarySoft }]}><Text style={{ color: mode === "designs" ? colors.primary : colors.muted, fontFamily: "Manrope_700Bold" }}>Designs</Text></Pressable><Pressable onPress={() => setMode("products")} style={[styles.tab, mode === "products" && { backgroundColor: colors.primarySoft }]}><Text style={{ color: mode === "products" ? colors.primary : colors.muted, fontFamily: "Manrope_700Bold" }}>Products</Text></Pressable></View><ScrollView horizontal showsHorizontalScrollIndicator={false}>{mode === "designs" ? designs.map((item) => <View key={item.id} style={{ width: cardWidth }}><CatalogCard eyebrow={item.garment_type} imageUrl={item.thumbnail_url || item.image_url} onPress={() => router.push({ pathname: "/design/[id]", params: { id: String(item.id) } })} price={item.base_price} title={item.title} /></View>) : products.map((item) => <View key={item.id} style={{ width: cardWidth }}><CatalogCard eyebrow={`${item.category} · ${item.unit}`} imageUrl={item.thumbnail_url || item.image_url} onPress={() => router.push({ pathname: "/product/[id]", params: { id: String(item.id) } })} price={item.price} title={item.title} /></View>)}</ScrollView>{(mode === "designs" ? designs : products).length === 0 && <EmptyState message={`Published ${mode} from this shop will appear here.`} title={`No ${mode} yet`} />}</Screen>
}

const styles = StyleSheet.create({ hero: { alignItems: "center", borderRadius: 20, borderWidth: 1, flexDirection: "row", gap: 13, marginBottom: 13, padding: 15 }, logo: { alignItems: "center", borderRadius: 18, height: 70, justifyContent: "center", overflow: "hidden", width: 70 }, logoImage: { height: "100%", width: "100%" }, tabs: { borderBottomWidth: 1, flexDirection: "row", gap: 7, marginBottom: 12, marginTop: 24, paddingBottom: 10 }, tab: { borderRadius: 12, paddingHorizontal: 14, paddingVertical: 10 } })
